package com.kaipai.service.ai.profileimport;
import static org.junit.jupiter.api.Assertions.*; import com.kaipai.model.ai.entity.*; import java.nio.file.*; import java.util.*; import org.junit.jupiter.api.Test;
class AiProfileImportPersistenceShapeTest { @Test void requestAuditAndConfigCannotPersistSourceOrPlainSecret()throws Exception{assertNoFields(AiProfileImportRequestAudit.class,"rawText","response","rawResponse","sourceText","evidence");assertNoFields(AiProfileImportConfig.class,"apiKey","secret");String sql=Files.readString(Path.of("src/main/resources/db/migration/V20260723_004__ai_profile_import_governance.sql")).toLowerCase(Locale.ROOT);for(String forbidden:List.of("raw_text","raw_response","source_text","api_key"))assertFalse(sql.contains(forbidden));assertTrue(sql.contains("unique key uk_ai_profile_import_request_user_request"));} @Test void permissionMigrationContainsPageAndEveryGovernedAction()throws Exception{String sql=Files.readString(Path.of("src/main/resources/db/migration/V20260723_005__ai_profile_import_permission_alignment.sql"));for(String code:List.of("page.system.ai-profile-import","action.system.ai-profile-import.update","action.system.ai-profile-import.secret","action.system.ai-profile-import.test","action.system.ai-profile-import.audit"))assertTrue(sql.contains(code));} private void assertNoFields(Class<?> type,String... names){Set<String> fields=new HashSet<>();for(var field:type.getDeclaredFields())fields.add(field.getName());for(String name:names)assertFalse(fields.contains(name));}}
